package state

//go:generate optgen generate

import "google.golang.org/protobuf/reflect/protoreflect"

// DefaultField is the default state field of [Machine.Transition] (see
// [WithField]).
const DefaultField protoreflect.Name = "state"

// options configures a [Machine]. Tunables are generated by optgen.
type options struct {
	// WithField names the resource field [Machine.Transition] reads and sets,
	// by its proto name. An empty name keeps the default.
	field protoreflect.Name `optgen:"default=DefaultField"`
}
